        Y = [ones(nTrials,1) ; ones(nTrials,1) ; -ones(nTrials,1) ; -ones(nTrials,1)]; % right hits, left hits, left miss, right miss
        % Y = [ones(nhits,1) ; -ones(nhits,1) ; ones(nmiss,1) ; -ones(nmiss,1)]; % right hits, left hits, left miss, right miss

        % input
        X = obj(sessix).trialdat(:,:,trials.all);
        X = permute(X,[1 3 2]); % (time,trials, clu)
        Xmax = max(X(:));
        Xmin = min(X(:));
        Range = Xmax - Xmin;
        Xnrm = ((X - Xmin)/Range - 0.5) * 2;
        X = Xnrm; clear Xnrm;

        % train/test split
        [trials.train,trials.trainidx] = datasample(trials.all,round(numel(trials.all)*rez.train),'Replace',false);
        trials.testidx = find(~ismember(trials.all,trials.train));
        trials.test = trials.all(trials.testidx);

        in.train.y = Y(trials.trainidx);
        in.test.y  = Y(trials.testidx);
        in.train.X = X(:,trials.trainidx,:);
        in.test.X  = X(:,trials.testidx,:);

        % decoding

        acc(:,sessix,ifeat) = DLC_ChoiceDecoder(in,rez,trials);


        % shuffle labels for a 'null' distribution


        Y = randsample(Y,numel(Y));

        % train/test split

        in.train.y = Y(trials.trainidx);
        in.test.y  = Y(trials.testidx);

        for ishuf = 1:rez.nShuffles
            acc_shuf(:,sessix,ishuf,ifeat) = DLC_ChoiceDecoder(in,rez,trials);
        end


    end

end

acc_shuf_ = reshape(acc_shuf,size(acc_shuf,1),size(acc_shuf,2)*size(acc_shuf,3));

function acc = DLC_ChoiceDecoder(in,rez,trials)

% bootstrap, and sessions happen outside this function

X_train = in.train.X;
y_train = in.train.y;
X_test = in.test.X;
y_test = in.test.y;


ix = 1;
for i = 1:rez.dt:(size(X_train,1)-rez.dt) % each timepoint

    ixs = i:(i+rez.dt-1);

    % train
    x_train = squeeze(nanmean(X_train(ixs,:,:),1));
    x_train = fillmissing(x_train,'constant',0);
    if size(x_train,1) == 1
        x_train = x_train';
    end

    mdl = fitclinear(x_train',y_train','Learner','svm','KFold',rez.nFolds,'ObservationsIn','columns');

    pred = kfoldPredict(mdl);

    acc(ix) = sum(pred == y_train) / numel(y_train);
    ix = ix + 1;
end


end% find offset between neural data file start and video file start
function vidshift = findVideoOffset(obj)
bitStart = mode(obj.bp.ev.bitStart);
vidFileOffset = mode(obj.sglx.bitcode.bitstart) / obj.sglx.fs;
vidshift = vidFileOffset - bitStart; % (s)
endfunction outcome = getOutcome(obj)

% get choice on previous trial

outcome = cell(numel(obj),1);

for sessix = 1:numel(obj)
    outcome{sessix} = obj(sessix).bp.hit; 
    ignore = logical(obj(sessix).bp.no);
    outcome{sessix}(ignore) = nan;
end


