def ch(f,r): return ''.join(chr(int(x)) for x in np.ravel(f[r][()])).strip().lower()
def v(f,r): return np.ravel(f[r][()]).astype(float)
for win in [(-2.5,2.5),(-3,2.5),(-2.5,1.5),(-3,3)]:
 keep=tot=0
 for key,ps in context.items():
  with h5py.File(Path('/app/data/Ephys_Behavior')/f'data_structure_{key}.mat','r') as f:
   go=np.ravel(f['obj/bp/ev/goCue'][()]); nt=int(f['obj/bp/Ntrials'][0,0])
   for pi,r in enumerate(f['obj/clu'][:,0],1):
    if pi not in ps: continue
    g=f[r]
    for i in range(g['quality'].shape[0]):
     if ch(f,g['quality'][i,0]) in bad: continue
     tot+=1; tr=v(f,g['trial'][i,0]).astype(int); tm=v(f,g['trialtm'][i,0]); a=tm-go[tr-1]; rate=((a>=win[0])&(a<win[1])).sum()/nt/(win[1]-win[0]); keep+=rate>1
 print(win,tot,keep)
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":3000});
